const b = ($input.first() && $input.first().json && $input.first().json.body) || {};
const rd = Number(b.rd != null ? b.rd : b.readiness) || 0;
const streak = Number(b.streak) || 0;
const gym = Number(b.gymThisWeek) || 0;
const mus = b.mus || {}; const ks = Object.keys(mus);
let avgFat = Number(b.avgFat);
if (isNaN(avgFat) && ks.length) { avgFat = ks.reduce((a, k) => a + Number((mus[k] && mus[k].f) || 0), 0) / ks.length; }
avgFat = Math.round(avgFat || 0);
const band = rd >= 75 ? 'otima' : rd >= 55 ? 'adequada' : rd >= 40 ? 'comprometida' : 'critica';
let flag = 'DADOS', msg;
if (band === 'critica') { flag = 'RECUPERAR'; msg = 'Prontidao critica em ' + rd + '%. Hoje o melhor treino e dormir e comer — forcar agora atrasa-te.'; }
else if (avgFat > 65) { flag = 'DELOAD'; msg = 'Fadiga media em ' + avgFat + '% — corpo a pedir semana leve. Deload nao e fraqueza, e estrategia.'; }
else if (band === 'otima' && streak >= 3) { flag = 'JANELA'; msg = 'Prontidao ' + rd + '% e ' + streak + ' dias seguidos. Janela para puxar pesado — da para bater PR.'; }
else { msg = 'Recuperacao ' + band + ' (' + rd + '%). Da para treinar com qualidade, sem heroismo. ' + gym + ' estimulos esta semana.'; }
return [{ json: { coach: 'MUZY', flag, msg, readiness: rd, avgFat, band } }];
